powerpagecomponent.content:
{
  "description": "Exposes al_signoff to the portal Web API so a T&C Manager can attest to a completed remediation (PP-12, FR-023, BR-008). Sign-off is a create, which the Web API does support, so this needs no trigger column - and a separate table means create can be bound to the T&C Supervisor role alone.",
  "value": "true"
}
